"""Render meetings as a weekly text grid."""

from collections import defaultdict

from planner.model import Section

DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
DEFAULT_START = 8 * 60
DEFAULT_END = 21 * 60
LABEL = 5  # "HH:MM"
DEFAULT_WIDTH = 16


def _hm(minutes: int) -> str:
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def _blocks(rows: list[Section], start: int, end: int) -> dict[str, list[Section]]:
    by_day: dict[str, list[Section]] = defaultdict(list)
    for row in rows:
        if row.end <= start or row.start >= end:
            continue
        by_day[row.day].append(row)
    for day in by_day:
        by_day[day].sort(key=lambda r: (r.start, r.end, r.course, r.section))
    return by_day


def active_days(rows: list[Section]) -> list[str]:
    """Days (Mon..Sun) on which at least one meeting happens."""
    present = {row.day for row in rows}
    return [day for day in DAYS if day in present]


def _label(row: Section) -> str:
    text = f"{row.course} {row.section}".strip()
    if row.location:
        text += f" @{row.location}"
    return text


def grid(
    rows: list[Section],
    *,
    start: int = DEFAULT_START,
    end: int = DEFAULT_END,
    width: int = DEFAULT_WIDTH,
) -> str:
    """Return an ASCII weekly grid with one column per day that has a meeting."""
    if width < 8:
        raise ValueError("cell width must be at least 8 characters")
    days = active_days(rows)
    if not days:
        return "(no meetings)\n"
    if start >= end:
        raise ValueError("grid start must be before grid end")
    by_day = _blocks(rows, start, end)
    offset = LABEL + 1

    def place(line: list[str], day_index: int, column: int, text: str) -> None:
        base = offset + day_index * (width + 1)
        if base + column + len(text) > len(line):
            line.extend(" " * (base + column + len(text) - len(line)))
        line[base + column : base + column + len(text)] = text

    def line_of(cells: list[tuple[int, str]]) -> str:
        out: list[str] = [" "] * (offset + len(days) * (width + 1))
        for day_index, column, text in cells:
            place(out, day_index, column, text)
        return "".join(out).rstrip()

    header: list[tuple[int, str]] = []
    for index, day in enumerate(days):
        header.append((index, 0, day.center(width)))
    lines = [line_of(header)]

    rows_out: list[str] = []
    hour_header = line_of([])
    rows_out.append(hour_header.rstrip())
    busy = {day: 0 for day in days}
    for row in rows:
        if row.day in busy:
            busy[row.day] += 1

    for minute in range(start, end, 60):
        cells: list[tuple[int, str]] = []
        body = [" "] * (offset + len(days) * (width + 1))
        out = body
        label = _hm(minute)
        out[0:LABEL] = label

        def put(day_index: int, column: int, text: str) -> None:
            base = offset + day_index * (width + 1)
            text = text[: max(0, width - column)]
            out[base + column : base + column + len(text)] = text

        for day_index, day in enumerate(days):
            put(day_index, 0, "|")
            for row in by_day.get(day, []):
                if minute < row.start or minute >= row.end:
                    continue
                lasted = row.end - row.start
                rows_count = max(1, (lasted + 59) // 60)
                slot = (row.start - start) // 60 if row.start >= start else 0
                row_height = max(1, rows_count // len(by_day[day]))

                first = row.start < start
                show_time = not first or minute == start
                if show_time:
                    put(day_index, 1, _hm(row.start))
                    put(day_index, 6, "-" + _hm(row.end))
                    put(day_index, 14, "")  # noop keeps column math obvious
                return ""

        return ""

    # Fallback simple rendering is never reached; see grid_simple.
    return "\n".join(lines) + "\n"


def grid_simple(
    rows: list[Section],
    *,
    start: int = DEFAULT_START,
    end: int = DEFAULT_END,
    width: int = DEFAULT_WIDTH,
) -> str:
    """Return an ASCII weekly grid with one column per day that has a meeting."""
    if width < 10:
        raise ValueError("cell width must be at least 10 characters")
    if start >= end:
        raise ValueError("grid start must be before grid end")
    days = active_days(rows)
    if not days:
        return "(no meetings)\n"
    by_day = _blocks(rows, start, end)
    offset = LABEL + 1
    total = offset + len(days) * (width + 1)

    def line_of(pieces: list[tuple[int, int, str]]) -> str:
        out = [" "] * total
        for day_index, column, text in pieces:
            base = offset + day_index * (width + 1) + column
            for i, char in enumerate(text):
                if 0 <= base + i < total:
                    out[base + i] = char
        return "".join(out).rstrip()

    lines = [line_of([(i, max(0, (width - len(day)) // 2), day) for i, day in enumerate(days)])]
    for minute in range(start, end, 60):
        pieces: list[tuple[int, int, str]] = [(0, 0, _hm(minute))]
        for day_index, day in enumerate(days):
            pieces.append((day_index, 0, "|"))
            for row in by_day.get(day, []):
                if minute < row.start or minute >= row.end:
                    continue
                if minute == row.start or (row.start < start and minute == start):
                    text = _hm(row.start) + "-" + _hm(row.end)
                    label = _label(row)
                    if len(text) + 1 + len(label) <= width - 2:
                        text = text + " " + label
                    pieces.append((day_index, 1, text[: width - 1]))
        lines.append(line_of(pieces))
    return "\n".join(lines) + "\n"

"""Render meetings as a weekly text grid."""

from collections import defaultdict

from planner.model import Section

DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
DEFAULT_START = 8 * 60
DEFAULT_END = 21 * 60
LABEL = 5  # width of "HH:MM"
DEFAULT_WIDTH = 18


def _hm(minutes: int) -> str:
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def _block(row: Section) -> int:
    """Grid row index (relative hours from the first hour of the grid)."""
    return row.start // 60


def active_days(rows: list[Section]) -> list[str]:
    """Days (Mon..Sun order) on which at least one meeting happens."""
    present = {row.day for row in rows}
    return [day for day in DAYS if day in present]


def _label(row: Section) -> str:
    text = f"{row.course} {row.section}".strip()
    if row.location:
        text += f" {row.location}"
    return text


def _visible(rows: list[Section], start: int, end: int) -> list[Section]:
    return [row for row in rows if row.end > start and row.start < end]


def _layout(slots: list[Section], width: int) -> list[str]:
    """Split one hour cell into lines shared by every meeting starting there."""
    pieces = []
    for row in slots:
        first = _hm(row.start)
        last = _hm(row.end)
        pieces.append([first + "-" + last, _label(row)])
    lines = []
    for index in range(max(len(p) for p in pieces)):
        line = " ".join(p[index] if index < len(p) else "" for p in pieces)
        lines.append(line[: width - 1])
    return lines


def render(
    rows: list[Section],
    *,
    start: int | None = None,
    end: int | None = None,
    width: int = DEFAULT_WIDTH,
    days: list[str] | None = None,
) -> str:
    """Return an ASCII weekly grid.

    ``start``/``end`` confine the grid to hours (minutes after midnight); by
    default the grid spans the meetings. ``days`` forces the columns, otherwise
    only days with a meeting are shown. Each cell lists every meeting that
    starts in that hour.
    """
    if width < 12:
        raise ValueError("cell width must be at least 12 characters")
    chosen = list(days) if days is not None else active_days(rows)
    bad = [day for day in chosen if day not in DAYS]
    if bad:
        raise ValueError("unknown day(s): " + ", ".join(bad))
    if not chosen:
        return "(no meetings)\n"
    low = start if start is not None else min((r.start for r in rows), default=DEFAULT_START)
    high = end if end is not None else max((r.end for r in rows), default=DEFAULT_END)
    low -= low % 60
    high = min(24 * 60, -(-high // 60) * 60)
    if low >= high:
        raise ValueError("grid start must be before grid end")
    visible = _visible(rows, low, high)

    first_col = LABEL + 1
    total = first_col + len(chosen) * (width + 1)

    def line_of(lead: str, cells: dict[int, str]) -> str:
        out = list(lead.ljust(first_col - 1) + " ")
        out = [" "] * first_col
        for i, char in enumerate(lead):
            out[i] = char
        for index, text in cells.items():
            base = first_col + index * (width + 1)
            for i, char in enumerate(text[:width]):
                out[base + i] = char
        return "".join(out).rstrip()

    header = {
        index: day.center(width) for index, day in enumerate(chosen)
    }
    lines = [line_of("", header)]
    by_day: dict[str, list[Section]] = defaultdict(list)
    for row in visible:
        if row.day in chosen:
            by_day[row.day].append(row)
    for day in by_day:
        by_day[day].sort(key=lambda r: (r.start, r.end, r.course, r.section))

    for slot_start in range(low, high, 60):
        cells = {
            index: _layout(
                [r for r in by_day.get(day, []) if _block(r) * 60 == slot_start],
                width,
            )
            for index, day in enumerate(chosen)
        }
        depth = max((len(c) for c in cells.values()), default=0)
        if depth == 0:
            lines.append(line_of(f"{_hm(slot_start)}|", {}))
            continue
        for depth_index in range(depth):
            label = f"{_hm(slot_start)}|" if depth_index == 0 else "     |"
            row_cells = {
                index: (c[depth_index] if depth_index < len(c) else " ")
                for index, c in cells.items()
            }
            lines.append(line_of(label, row_cells))
    return "\n".join(lines) + "\n"

